const TenantConfig = require("../../../../../libs/custom-mongo-storage-plugin/tenants");
const storageModule = require("../../../../../libs/custom-mongo-storage-plugin");
module.exports = {
    init: function() {
       
    },
    create: async function(req, res) {
        try {
             const { userId } = req.admin;
             req.body.createdBy = userId;
            await TenantConfig.create(req.body);
            await storageModule.populateSubflows(req.body.accountId, userId);
            res.status(201).json({message: 'Tenant created successfully'});
        } catch (error) {
            console.error(error);
            res.status(500).send(error);
        }
    }
}